package in.asmj.ride.web;
import in.asmj.ride.model.UserAccount;import in.asmj.ride.repo.UserAccountRepository;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.security.crypto.password.PasswordEncoder;import java.security.SecureRandom;import java.time.Instant;import org.springframework.beans.factory.annotation.Value;
@Controller public class AuthController {
 private final UserAccountRepository r;private final PasswordEncoder e;private final SecureRandom random=new SecureRandom();
 @Value("${app.otp.dev-mode:false}") private boolean devOtpMode;
 public AuthController(UserAccountRepository r,PasswordEncoder e){this.r=r;this.e=e;}
 @GetMapping("/")String home(){return "index";}@GetMapping("/login")String login(){return "login";}@GetMapping("/register")String register(){return "register";}
 @PostMapping("/register")String register(@RequestParam String name,@RequestParam String email,@RequestParam String mobile,@RequestParam String password,@RequestParam String role,Model m){if(name.isBlank()||!mobile.matches("[0-9]{10}")||password.length()<8||!email.contains("@")){m.addAttribute("error","Please enter valid details; password must be at least 8 characters.");return "register";}if(r.findByEmailIgnoreCase(email).isPresent()){m.addAttribute("error","Email already registered.");return "register";}if(!role.matches("CUSTOMER|DRIVER|FLEET_OWNER"))role="CUSTOMER";UserAccount u=new UserAccount();u.setName(name);u.setEmail(email.toLowerCase());u.setMobile(mobile);u.setPasswordHash(e.encode(password));u.setRole(role);u.setStatus(role.equals("CUSTOMER")?"APPROVED":"PENDING");r.save(u);return "redirect:/otp/request?email="+u.getEmail();}
 @GetMapping("/otp/request")String otp(@RequestParam String email,Model m){m.addAttribute("email",email);return "otp";}
 @PostMapping("/otp/request")String send(@RequestParam String email,Model m){var o=r.findByEmailIgnoreCase(email);if(o.isEmpty()){m.addAttribute("error","Account not found");m.addAttribute("email",email);return "otp";}var u=o.get();if(!devOtpMode){m.addAttribute("error","OTP delivery is not configured. Please contact the administrator.");m.addAttribute("email",email);return "otp";}
 String code=String.format("%06d",random.nextInt(1000000));u.setOtpHash(e.encode(code));u.setOtpExpiry(Instant.now().plusSeconds(300));r.save(u);m.addAttribute("email",email);m.addAttribute("devOtp",code);m.addAttribute("success","Development OTP generated (5-minute expiry).");return "otp";}
 @PostMapping("/otp/verify")String verify(@RequestParam String email,@RequestParam String otp,Model m){var o=r.findByEmailIgnoreCase(email);if(o.isEmpty()){m.addAttribute("error","Account not found");m.addAttribute("email",email);return "otp";}var u=o.get();if(u.getOtpHash()==null||u.getOtpExpiry()==null||Instant.now().isAfter(u.getOtpExpiry())||!e.matches(otp,u.getOtpHash())){m.addAttribute("error","Invalid or expired OTP");m.addAttribute("email",email);return "otp";}u.setMobileVerified(true);u.setOtpHash(null);u.setOtpExpiry(null);r.save(u);m.addAttribute("success","Mobile verified. Please sign in.");return "login";}
 @GetMapping("/dashboard")String dashboard(org.springframework.security.core.Authentication a){var u=r.findByEmailIgnoreCase(a.getName()).orElseThrow();return "redirect:"+ (u.getRole().equals("ADMIN")?"/admin":u.getRole().equals("CUSTOMER")?"/customer":u.getRole().equals("DRIVER")?"/driver":"/partner");}
}